    source: c.source || 'facebook',
    page_id: String(c.page_id || c.parent_id || ''),
    post_id: String(c.post_id || ''),
    comment_id: String(c.comment_id || c.id || ''),
    message: String(c.message || '').slice(0, 4000),
    from_id: String((c.from && c.from.id) || c.from_id || c.user_id || ''),
    from_name: String((c.from && c.from.name) || c.from_name || c.name || 'inconnu'),
    manychat_subscriber_id: String(c.subscriber_id || c.manychat_subscriber_id || ''),
    received_at: new Date().toISOString()
  }});
}
if (body.entry && Array.isArray(body.entry)) {
  for (const entry of body.entry) {
    for (const ch of (entry.changes || [])) {
      const v = ch.value || {};
      if (ch.field === 'feed' && (v.item === 'comment' || v.comment_id)) {
        addComment({ ...v, page_id: entry.id, source: 'facebook_webhook' });
      }
    }
  }
} else {
  addComment({
    source: 'manychat_or_manual',
    page_id: body.page_id,
    post_id: body.post_id,
