    from_name: body.from_name || body.name || body.first_name,
    subscriber_id: body.subscriber_id || body.manychat_subscriber_id
  });
}
return items.length ? items : [{ json: { skipped: true, reason: 'Aucun commentaire exploitable detecte', raw: body } }];

