// Format 2 (prod) : { entry: [...] }  
// Format 3 (test FB) : { body: { sample: { field, value } } }
// Format 4 (test FB) : { sample: { field, value } }

const body = raw.body || raw;

// --- Traitement des vrais événements (entry) ---
const entries = body.entry || [];
const comments = [];

for (const entry of entries) {
  const changes = entry.changes || [];
  for (const change of changes) {
    const val = change.value || {};
    const field = change.field || '';

    // Accepter : feed + item=comment (add OU edited)
    if (field === 'feed' && val.item === 'comment') {
      comments.push({
        comment_id: val.comment_id || val.id || '',
        post_id: val.post_id || entry.id || '',
        message: val.message || '',
        from_id: val.from?.id || '',
        from_name: val.from?.name || 'Anonyme',
        created_time: val.created_time || '',
        parent_id: val.parent_id || null,
        verb: val.verb || 'add',
        _source: 'real_event'
      });
    }

    // Accepter aussi : feed + item=post (pour logs)
    if (field === 'feed' && val.item === 'status') {
      comments.push({
        comment_id: val.post_id || '',
        post_id: val.post_id || '',
        message: val.message || '',
        from_id: val.from?.id || '',
        from_name: val.from?.name || 'Anonyme',
        created_time: val.created_time || '',
        parent_id: null,
        verb: val.verb || 'add',
        _source: 'post_event'
      });
    }
  }
}

