    comments.push({
      comment_id: val.comment_id || 'test_id',
      post_id: val.post_id || 'test_post',
      message: val.message || 'Test Facebook',
      from_id: val.from?.id || '',
      from_name: val.from?.name || 'Test Page',
      created_time: val.created_time || '',
      parent_id: null,
      verb: 'add',
      _source: 'facebook_test_sample'
    });
  }
}

// Si toujours rien → log pour debug
if (comments.length === 0) {
