} catch (e) {
  const lower = (commentData.message || '').toLowerCase();
  const banned = ($vars.BANNED_KEYWORDS || 'spam,arnaque,nul').split(',').map(k => k.trim());
  const hasKw = banned.some(k => lower.includes(k));
  analysis = {
    action: hasKw ? 'delete' : lower.includes('?') ? 'reply' : 'keep',
    reason: 'Fallback heuristique',
    reply: null, confidence: 0.5, category: hasKw ? 'négatif' : 'neutre'
  };
}

return [{
  json: {
    ...commentData,
    action: analysis.action || 'keep',
    reason: analysis.reason || '',
    ai_reply: analysis.reply || null,
    confidence: analysis.confidence || 0,
    category: analysis.category || 'neutre',
    analyzed_at: new Date().toISOString()
  }
}];

