            postId: v.post_id,
            fromId: v.from?.id,
            fromName: v.from?.name || 'Anonyme',
            message: v.message || '',
            verb: v.verb, // 'add', 'edited', 'remove'
            createdTime: v.created_time,
            pageId: entry.id
          });
        }
      }
    }
  }
}

