const payload = { session: source.session, chatId: source.chatId, text: draft };
const encoded = Buffer.from(JSON.stringify(payload), 'utf8').toString('base64url');
const approvalBase = 'https://n8n.sakamomo.tech/webhook/wa-openclaw-approve-v3';
const approveUrl = approvalBase + '?action=approve&secret=600ea6fff7eaa86531059e655ae5cea7ac39a124&payload=' + encoded;
const rejectUrl = approvalBase + '?action=reject&secret=600ea6fff7eaa86531059e655ae5cea7ac39a124&payload=' + encoded;

const adminText = [
  '🧠 Brouillon WhatsApp OpenClaw',
  '',
  'Contact: ' + source.chatId,
  source.senderName ? 'Nom: ' + source.senderName : '',
  '',
  'Message reçu:',
  source.incomingText,
  '',
