const body = $input.first().json.body;
const comments = [];

if (!body?.entry) return [];

for (const entry of body.entry) {
  if (!entry.changes) continue;
  for (const change of entry.changes) {
    if (change.field === 'feed' && change.value?.item === 'comment' && change.value?.verb === 'add') {
      const v = change.value;
      comments.push({
        comment_id: v.comment_id,
        post_id: v.post_id,
        message: v.message,
        from_id: v.from?.id || '',
        from_name: v.from?.name || 'Anonyme',
        created_time: v.created_time,
        parent_id: v.parent_id || null
      });
    }
  }
}

return comments.map(c => ({ json: c }));

// Préparer le prompt pour l'AI Agent
const comment = $input.first().json;
const pageContext = $vars.PAGE_CONTEXT || 'Page professionnelle, soyez courtois et serviable.';
const bannedKw = $vars.BANNED_KEYWORDS || 'spam, arnaque, nul, insulte, fake, escroc';
const replyLang = $vars.REPLY_LANG || 'français';

const prompt = `Tu es un agent de modération pour une page Facebook.

Contexte de la page: ${pageContext}
Mots-clés/thèmes interdits: ${bannedKw}
Langue des réponses: ${replyLang}

Commentaire à analyser:
- Auteur: ${comment.from_name}
- Message: "${comment.message}"

Réponds UNIQUEMENT en JSON valide (sans markdown, sans backticks) :
{
  "action": "delete" | "reply" | "keep",
  "reason": "explication courte en français",
  "reply": "texte de réponse si action=reply, sinon null",
  "confidence": 0.0,
  "category": "négatif" | "question" | "positif" | "spam" | "neutre"
}

Règles:
- delete: offensant, spam, insulte, négatif grave, mots-clés interdits
- reply: question directe ou commentaire nécessitant une réponse pro
- keep: positif ou neutre sans action nécessaire
- Si reply: répondre en ${replyLang}, professionnel et chaleureux, max 3 phrases`;

return [{
  json: {
    ...comment,
    agent_prompt: prompt
  }
}];

// Parser la réponse JSON de l'AI Agent
const agentOutput = $input.first().json.output || $input.first().json.text || '';
const commentData = $('🔧 Extraire Commentaires').first().json;

let analysis;
try {
  const clean = agentOutput.replace(/```json|```/g, '').trim();
  // Extraire le JSON si du texte l'entoure
  const match = clean.match(/\{[\s\S]*\}/);
  analysis = JSON.parse(match ? match[0] : clean);
} catch (e) {
  // Fallback heuristique si parsing échoue
  const lower = (commentData.message || '').toLowerCase();
  const banned = ($vars.BANNED_KEYWORDS || 'spam,arnaque,nul').split(',').map(k => k.trim());
  const hasKw = banned.some(k => lower.includes(k));
  analysis = {
    action: hasKw ? 'delete' : lower.includes('?') ? 'reply' : 'keep',
    reason: 'Fallback heuristique (erreur parsing IA)',
    reply: null,
    confidence: 0.5,
    category: hasKw ? 'négatif' : 'neutre'
  };
}

return [{
  json: {
    ...commentData,
    action: analysis.action || 'keep',
    reason: analysis.reason || '',
    ai_reply: analysis.reply || null,
    confidence: analysis.confidence || 0,
    category: analysis.category || 'neutre',
    analyzed_at: new Date().toISOString()
  }
}];

